// A deck, as a .pptx file.
//
// The package is a ZIP of XML parts: the presentation, one master, one layout,
// a theme, and a part per slide. Nothing here is generated by a library — see
// `shapes.ts` for why.

import { zipSync, strToU8 } from 'fflate';
import { EMU_PER_INCH, EMU_PER_PT, SLIDE, type Block, type Deck, type Slide } from './model.js';
import {
  drawing, picture, resetIds, table, textBox, type Frame, type Placement,
} from './shapes.js';
import {
  APP, CONTENT_TYPES, CORE, PRESENTATION, PRESENTATION_RELS, PRES_PROPS, ROOT_RELS,
  SLIDE_LAYOUT, SLIDE_LAYOUT_RELS, SLIDE_MASTER, SLIDE_MASTER_RELS, TABLE_STYLES, THEME,
  VIEW_PROPS, slideRels, slideXml,
} from './xml.js';

export interface PptxOptions {
  /** The theme's fonts, so the deck looks like the document it came from. */
  readonly headingFont?: string;
  readonly bodyFont?: string;
}

const MARGIN = Math.round(EMU_PER_INCH * 0.55);
const TITLE_HEIGHT = Math.round(EMU_PER_INCH * 0.72);
const FOOT_HEIGHT = Math.round(EMU_PER_INCH * 0.3);

/** Pictures gathered while the slides are written. */
interface Media {
  readonly names: string[];
  readonly bytes: Uint8Array[];
}

export function writePptx(deck: Deck, options: PptxOptions = {}): Uint8Array {
  const media: Media = { names: [], bytes: [] };

  // Slides are written first because they are what gathers the pictures, but
  // the package is assembled below in the order a reader expects: the content
  // types come first, and a reader that takes the first entry literally — as
  // LibreOffice does — refuses the file otherwise.
  const rels: string[] = [];
  const slides = deck.slides.map((slide, index) => {
    resetIds();
    const used: { id: number; target: string }[] = [];
    const placements: Placement[] = [];
    const body = slideBody(slide, index + 1, deck.slides.length, used, media, placements);
    rels.push(slideRels(used));
    return slideXml(body, placements.map(mark).join(' '));
  });

  const files: Record<string, Uint8Array> = {};
  files['[Content_Types].xml'] = strToU8(CONTENT_TYPES(slides.length, media.names));
  files['_rels/.rels'] = strToU8(ROOT_RELS);
  files['docProps/core.xml'] = strToU8(CORE(deck.title));
  files['docProps/app.xml'] = strToU8(APP(slides.length));
  files['ppt/presentation.xml'] = strToU8(PRESENTATION(slides.length));
  files['ppt/_rels/presentation.xml.rels'] = strToU8(PRESENTATION_RELS(slides.length));
  files['ppt/slideMasters/slideMaster1.xml'] = strToU8(SLIDE_MASTER);
  files['ppt/slideMasters/_rels/slideMaster1.xml.rels'] = strToU8(SLIDE_MASTER_RELS);
  files['ppt/slideLayouts/slideLayout1.xml'] = strToU8(SLIDE_LAYOUT);
  files['ppt/slideLayouts/_rels/slideLayout1.xml.rels'] = strToU8(SLIDE_LAYOUT_RELS);
  files['ppt/presProps.xml'] = strToU8(PRES_PROPS);
  files['ppt/viewProps.xml'] = strToU8(VIEW_PROPS);
  files['ppt/tableStyles.xml'] = strToU8(TABLE_STYLES);
  files['ppt/theme/theme1.xml'] = strToU8(THEME(
    options.headingFont ?? 'Noto Sans CJK JP', options.bodyFont ?? 'Noto Sans CJK JP'));

  slides.forEach((xml, index) => {
    files[`ppt/slides/slide${index + 1}.xml`] = strToU8(xml);
    files[`ppt/slides/_rels/slide${index + 1}.xml.rels`] = strToU8(rels[index]!);
  });
  media.names.forEach((name, index) => { files[`ppt/media/${name}`] = media.bytes[index]!; });

  return zipSync(files, { level: 6 });
}

/** `dp:drawing=…` — read back by `read.ts`, ignored by everything else. */
function mark(placement: Placement): string {
  const round = (value: number): number => Math.round(value * 1000) / 1000;
  return `dp:drawing=${placement.source};scale=${round(placement.scale)}`
    + `;x=${Math.round(placement.originX)};y=${Math.round(placement.originY)}`;
}

function slideBody(
  slide: Slide, number: number, total: number,
  used: { id: number; target: string }[], media: Media, placements: Placement[],
): string {
  const parts: string[] = [];
  const hasTitle = slide.title !== undefined && slide.title !== '';
  const top = MARGIN + (hasTitle ? TITLE_HEIGHT : 0);
  const frame: Frame = {
    x: MARGIN, y: top,
    width: SLIDE.width - MARGIN * 2,
    height: SLIDE.height - top - MARGIN - FOOT_HEIGHT,
  };

  if (hasTitle) {
    parts.push(textBox(
      { kind: 'text', paragraphs: [[plain(slide.title!)]] },
      { x: MARGIN, y: MARGIN, width: SLIDE.width - MARGIN * 2, height: TITLE_HEIGHT },
      24, '#1c1f24', 'l',
    ));
  }

  // One thing per slide is the shape this output is for; when a slide carries
  // more, they share the height in the order they were written — text as much
  // as its lines need, and a picture, a drawing or a table the rest.
  const blocks = slide.blocks;
  const heights = shares(blocks, frame.height);
  let y = frame.y;
  for (const [index, block] of blocks.entries()) {
    const height = heights[index]!;
    const own: Frame = { x: frame.x, y, width: frame.width, height };
    parts.push(blockXml(block, own, used, media, placements));
    y += height;
  }

  const foot = slide.foot ? `${slide.foot}　${number} / ${total}` : `${number} / ${total}`;
  parts.push(textBox(
    { kind: 'text', paragraphs: [[plain(foot)]] },
    { x: MARGIN, y: SLIDE.height - MARGIN - FOOT_HEIGHT, width: SLIDE.width - MARGIN * 2, height: FOOT_HEIGHT },
    9, '#6b7280', 'l',
  ));
  return parts.join('');
}

/** The point size text is set in: prose at 14, code a size smaller. */
const PROSE_SIZE = 14;
const CODE_SIZE = 11;
/** The least a block that is not text keeps, as a share of the slide. */
const FIGURE_SHARE = 0.4;

function isCode(block: Block): boolean {
  return block.kind === 'text' && block.paragraphs.length > 0
    && block.paragraphs.every(runs => runs.length === 0 || runs.every(run => run.code));
}

/** The height a block of text needs at its own size, in EMU. */
function needed(block: Block): number | undefined {
  if (block.kind !== 'text') return undefined;
  const size = isCode(block) ? CODE_SIZE : PROSE_SIZE;
  return Math.round((block.paragraphs.length * size * 1.3 + 10) * EMU_PER_PT);
}

/**
 * How the height of a slide is shared. Text takes what its lines need; what is
 * left goes to the pictures, drawings and tables in equal parts — but never so
 * little that a figure becomes a thumbnail, in which case the text gives way.
 */
function shares(blocks: readonly Block[], height: number): number[] {
  const wants = blocks.map(needed);
  const figures = wants.filter(want => want === undefined).length;
  const text = wants.reduce<number>((sum, want) => sum + (want ?? 0), 0);
  const room = figures === 0 ? height : height * (1 - FIGURE_SHARE);
  const scale = text > room ? room / text : 1;
  const textHeights = wants.map(want => (want === undefined ? 0 : Math.round(want * scale)));
  const left = height - textHeights.reduce((a, b) => a + b, 0);
  return wants.map((want, i) => (want === undefined ? Math.round(left / figures) : textHeights[i]!));
}

function blockXml(
  block: Block, frame: Frame, used: { id: number; target: string }[], media: Media,
  placements: Placement[],
): string {
  switch (block.kind) {
    case 'text': {
      // Text given less room than it needs is set smaller rather than spilling
      // over whatever is placed below it.
      const size = isCode(block) ? CODE_SIZE : PROSE_SIZE;
      const want = needed(block) ?? frame.height;
      const fitted = want > frame.height ? Math.max(7, size * (frame.height / want)) : size;
      return textBox(block, frame, Math.round(fitted * 2) / 2);
    }
    case 'table':  return table(block, frame, 10);
    case 'drawing': return drawing(block, frame, placement => placements.push(placement));
    case 'picture': {
      const decoded = dataUrl(block.data);
      if (!decoded) return '';
      const name = `image${media.names.length + 1}.${decoded.extension}`;
      media.names.push(name);
      media.bytes.push(decoded.bytes);
      const id = used.length + 2;
      used.push({ id, target: name });
      // Keep the picture's proportions inside the space it is given.
      const scale = Math.min(frame.width / (block.width * 9525), frame.height / (block.height * 9525));
      const width = block.width * 9525 * scale;
      const height = block.height * 9525 * scale;
      return picture(block, {
        x: frame.x + (frame.width - width) / 2,
        y: frame.y + (frame.height - height) / 2,
        width, height,
      }, id);
    }
  }
}

function plain(text: string): { text: string; bold: boolean; italic: boolean; code: boolean; colour: undefined } {
  return { text, bold: false, italic: false, code: false, colour: undefined };
}

function dataUrl(value: string): { bytes: Uint8Array; extension: string } | undefined {
  const comma = value.indexOf(',');
  if (!value.startsWith('data:') || comma < 0) return undefined;
  const type = value.slice(5, comma).split(';')[0] ?? '';
  const extension = type === 'image/jpeg' ? 'jpg' : type.slice(type.indexOf('/') + 1);
  if (!/^(png|jpg|gif)$/.test(extension)) return undefined;
  return { bytes: decode(value.slice(comma + 1)), extension };
}

function decode(base64: string): Uint8Array {
  const CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const clean = base64.replace(/[^A-Za-z0-9+/]/g, '');
  const out = new Uint8Array((clean.length * 3) >> 2);
  let at = 0;
  let buffer = 0;
  let bits = 0;
  for (const character of clean) {
    buffer = (buffer << 6) | CHARS.indexOf(character);
    bits += 6;
    if (bits < 8) continue;
    bits -= 8;
    out[at++] = (buffer >> bits) & 0xff;
  }
  return out.slice(0, at);
}
